import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as a,c as n,o as s,ag as e,G as l}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Google Flow","description":"Google 的 AI 创意工作室。用英文提示词生成几秒到十几秒的视频片段，再用 Scenebuilder 排成一部成片。本页讲清能不能用、10 分钟怎么做出第一段、积分怎么扣、常见坑怎么躲。","frontmatter":{"title":"Google Flow","description":"Google 的 AI 创意工作室。用英文提示词生成几秒到十几秒的视频片段，再用 Scenebuilder 排成一部成片。本页讲清能不能用、10 分钟怎么做出第一段、积分怎么扣、常见坑怎么躲。","domain":"product","tags":["coding-agent"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/gemini/flow.md","filePath":"zh/products/gemini/flow.md","lastUpdated":1795592559000}'),i={name:"zh/products/gemini/flow.md"};function d(g,t,h,p,c,u){const o=a("DocDiagram");return s(),n("div",null,[t[0]||(t[0]=e('<h1 id="google-flow" tabindex="-1">Google Flow <a class="header-anchor" href="#google-flow" aria-label="Permalink to &quot;Google Flow&quot;">​</a></h1><blockquote><p>Google 的 AI 创意工作室（官方叫法 <strong>AI creative studio</strong>）。它解决的问题是：前端工程师要给落地页、产品发布、内部评审配一段视频，但没拍过片子，也不想学剪辑软件。在 Flow 里，你用一句英文描述生成几秒到十几秒的片段，再把片段排成一部成片。</p><p>它<strong>不写代码</strong>。落地页宣传片、产品演示视频、场景分镜用它；要能点的页面用 <a href="./canvas.html">Canvas</a>。</p><p>入口：<a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">labs.google/fx/tools/flow</a>。帮助中心：<a href="https://support.google.com/flow" target="_blank" rel="noreferrer">support.google.com/flow</a>。</p></blockquote><p>本页的界面步骤、额度、地区信息<strong>截至 2026-11-24</strong> 逐页核对官方帮助中心。这些内容会变，以你界面里显示的为准。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>写给谁</strong></td><td>会写前端代码、没做过视频、没用过生成式视频工具的工程师</td></tr><tr><td><strong>先决条件</strong></td><td>一个 Google 账号；年满 18 岁并通过年龄验证；人在官方支持的国家或地区；电脑上有 Chrome 或 Edge 这类 Chromium 内核浏览器</td></tr><tr><td><strong>非目标</strong></td><td>不教剪辑软件；不教 Veo / Imagen 的 API 调用，那是 <a href="./ai-studio.html">AI Studio</a> 的事；不教 Flow Music，它做歌曲与 MV，积分体系分开</td></tr></tbody></table><h2 id="学完你能做什么" tabindex="-1">学完你能做什么 <a class="header-anchor" href="#学完你能做什么" aria-label="Permalink to &quot;学完你能做什么&quot;">​</a></h2><ul><li>判断自己<strong>能不能用</strong>：年龄、地区、套餐三条各是什么要求。</li><li>在 <strong>10 分钟内做出第一段视频</strong>并下载成文件。</li><li>按「手头有什么素材」<strong>选对生成模式</strong>：只有一句话、有一张图、有角色参考图，还是有一段现成视频。</li><li>用 Character、ingredients、首尾帧让<strong>多段素材里的角色和场景保持一致</strong>，再在 Scenebuilder 里排成一部成片。</li><li><strong>看懂积分怎么扣</strong>，认出常见报错：哪一步花钱，哪一步不花；每个坑对应官方哪句说明。</li></ul><h2 id="我能不能用-年龄、地区、语言、套餐" tabindex="-1">我能不能用：年龄、地区、语言、套餐 <a class="header-anchor" href="#我能不能用-年龄、地区、语言、套餐" aria-label="Permalink to &quot;我能不能用：年龄、地区、语言、套餐&quot;">​</a></h2><p>官方列了三条：年龄已验证且满 18 岁；人在支持地区；要用部分功能，还需要 Google AI 订阅。逐条展开。</p><h3 id="年龄-满-18-岁-且通过年龄验证" tabindex="-1">年龄：满 18 岁，且通过年龄验证 <a class="header-anchor" href="#年龄-满-18-岁-且通过年龄验证" aria-label="Permalink to &quot;年龄：满 18 岁，且通过年龄验证&quot;">​</a></h3><p>帮助中心原文：「Make sure your age is verified. You must be 18 years of age or older.」年龄验证挂在 Google 账号上。</p><h3 id="地区-中国大陆不在列表-香港、澳门、台湾在" tabindex="-1">地区：中国大陆不在列表，香港、澳门、台湾在 <a class="header-anchor" href="#地区-中国大陆不在列表-香港、澳门、台湾在" aria-label="Permalink to &quot;地区：中国大陆不在列表，香港、澳门、台湾在&quot;">​</a></h3><p><a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Where you can use Google Flow</a> 的说明是：「You can use the Google Flow Desktop platform and download the Google Flow mobile app in these countries and regions.」截至 2026-11-24，该页按字母序列出支持的国家与地区。</p><table tabindex="0"><thead><tr><th>我在哪里</th><th>在不在支持列表</th><th>依据（官方页原文）</th></tr></thead><tbody><tr><td>中国大陆</td><td><strong>不在</strong></td><td>列表按字母序排列，<code>Chile</code> 之后直接是 <code>Colombia</code>；整页没有出现 <code>China</code></td></tr><tr><td>香港</td><td><strong>在</strong></td><td><code>Hong Kong</code></td></tr><tr><td>澳门</td><td><strong>在</strong></td><td><code>Macau</code></td></tr><tr><td>台湾</td><td><strong>在</strong></td><td><code>Taiwan</code></td></tr></tbody></table><p>两条相关的官方说明：</p><ul><li><strong>VPN 没用</strong>：「VPNs will not enable access in unsupported regions.」</li><li><strong>买了 AI Pro 也不一定能用</strong>：「Google Flow is not currently available in all countries where Google AI Pro is offered.」官方建议买订阅前先查支持列表。</li></ul><p>部分功能还按地区收紧，同一页写明：</p><table tabindex="0"><thead><tr><th>功能</th><th>不开放的地区</th></tr></thead><tbody><tr><td>编辑上传的视频</td><td>欧洲经济区（EEA）、瑞士、英国</td></tr><tr><td>Avatar（你本人的形象）</td><td>欧洲经济区（EEA）、瑞士、英国</td></tr><tr><td>购买 AI credits</td><td>日本</td></tr></tbody></table><h3 id="语言-界面有简繁中文-提示词建议写英文" tabindex="-1">语言：界面有简繁中文，提示词建议写英文 <a class="header-anchor" href="#语言-界面有简繁中文-提示词建议写英文" aria-label="Permalink to &quot;语言：界面有简繁中文，提示词建议写英文&quot;">​</a></h3><p>官方页写「Google Flow is currently available in these languages」，列表里有 <code>Chinese (Simplified &amp; Traditional)</code> 和 <code>Cantonese</code>。界面语言跟 Google 账号设置走：「You can update your preferred language in your Google Account settings.」</p><p>提示词方面，官方的原话是建议英文，不是只支持英文：「For best results with our tools, we recommend using English prompts. While some of our products may support prompts in other languages, the quality of the generated output may vary depending on the language and complexity of the prompt.」</p><blockquote><p>本页旧版写「只能用英文向 Flow 发提示，回复也是英文」，出处标的是 <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro 权益页</a>。2026-11-24 核对：那句话（「Only English is supported for prompts and instructions」）在该页属于 <strong>Google Antigravity</strong> 一节，不是 Flow。Flow 自己的页面只说「建议英文」。</p></blockquote><h3 id="套餐-不订阅也能试用" tabindex="-1">套餐：不订阅也能试用 <a class="header-anchor" href="#套餐-不订阅也能试用" aria-label="Permalink to &quot;套餐：不订阅也能试用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>套餐</th><th>能用的功能</th><th>Flow 积分（截至 2026-11-24）</th></tr></thead><tbody><tr><td>无订阅</td><td>基础的视频生成与编辑。Omni Flash 1.2 可生成 3 到 10 秒；Veo 3.1 Lite 可生成 4、6、8 秒</td><td>每天 50</td></tr><tr><td>Google AI Plus / Pro / Ultra（Ultra 分两档）</td><td>完整功能。Omni Flash 1.2 可生成 3 到 15 秒；Omni Extend；把 360p 放大到 1080p（4K 仅 Ultra）；创建与 remix Tools</td><td>每天 50，另加每月 200 / 1,000 / 10,000 / 25,000（依次是 Plus、Pro、Ultra 两档）</td></tr><tr><td>符合条件的 Workspace 套餐</td><td>官方写「get access at no extra charge to Google Flow with 50 daily credits」</td><td>每天 50</td></tr></tbody></table><p>Workspace 这一条，官方列的套餐是 Business Starter / Standard / Plus、Enterprise Starter / Standard / Plus、G Suite Legacy Free Edition、Education Standard / Plus、Google AI Pro for Education。</p><p>不订阅有一条限制：高峰时段（官方写「roughly 2 PM to 5 PM UTC」，即北京时间 22:00 到次日 01:00）可能无法生成视频。这时仍可生成图片、使用 Agent。</p><h3 id="在哪里用-电脑网页版最全" tabindex="-1">在哪里用：电脑网页版最全 <a class="header-anchor" href="#在哪里用-电脑网页版最全" aria-label="Permalink to &quot;在哪里用：电脑网页版最全&quot;">​</a></h3><ul><li><strong>电脑网页版</strong>功能最全。官方：「For the most powerful editing features, go to Google Flow on a computer.」</li><li><strong>手机应用</strong>用于随手创作。官方：「For creation on the go, download the Google Flow app.」</li><li><strong>只在网页版有的功能</strong>：Omni Flash 1.2 的 Frames to Video 与 Omni Extend（官方均写「Currently only available at Google Flow on web」）；Tools（「Tools are currently available on web &amp; PC only」）。</li><li><strong>浏览器</strong>：用 Chromium 内核的，官方举例 Google Chrome 或 Edge。官方提醒其他浏览器与手机「are not yet fully optimized」，可能遇到 bug。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p>先认词。左列是你在界面和帮助中心里会见到的说法。</p><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th><th>为什么需要</th></tr></thead><tbody><tr><td><strong>project</strong>（项目）</td><td>一个容器，装着这部片子的全部素材</td><td>素材、Agent 会话、Tools 都按项目存放；换项目就是换一部片子</td></tr><tr><td><strong>asset</strong>（素材）</td><td>项目里生成的或上传的每一张图、每一段视频</td><td>加进提示词、排进时间线、下载，都以素材为单位</td></tr><tr><td><strong>generation</strong>（一次生成）</td><td>触发一次模型调用</td><td>积分按 generation 收，不按你点了几下</td></tr><tr><td><strong>take</strong>（候选片段）</td><td>一次生成可能出好几个结果，每一个是一个候选</td><td>候选多，挑的余地大，扣分也成倍</td></tr><tr><td><strong>frame</strong>（帧）</td><td>视频里的单张画面；首帧和尾帧决定一段视频从哪开始、到哪结束</td><td>镜头 A 的结尾要接上镜头 B 的开头，靠帧</td></tr><tr><td><strong>ingredients</strong>（参考素材）</td><td>生成时一并交给模型的参考图或参考视频</td><td>让同一个人、同一个物件在多个镜头里长得一样</td></tr><tr><td><strong>character</strong>（角色）</td><td>打包好、起了名字的一组视觉与声音参考</td><td>不用每次重新上传同一批图</td></tr><tr><td><strong>Scenebuilder</strong></td><td>把多个片段排成一条时间线的地方</td><td>单段只有几秒到十几秒，成片靠它拼</td></tr><tr><td><strong>scene</strong>（场景）</td><td>在 Scenebuilder 里排好的一串片段</td><td>预览、下载都以 scene 为单位</td></tr><tr><td><strong>Extend</strong></td><td>在一段视频后面再续几秒</td><td>好镜头太短时，不用整段重来</td></tr><tr><td><strong>Jump to</strong></td><td>让角色或物件换到新场景，外观不变</td><td>同一个角色换地点，不用重新描述</td></tr><tr><td><strong>aspect ratio</strong>（画幅）</td><td>画面的宽高比</td><td>落地页横幅与手机竖屏要的比例不同</td></tr><tr><td><strong>resolution</strong>（分辨率）</td><td>360p 草稿、720p 标准，可再放大到 1080p 或 4K</td><td>360p 便宜，适合先试构图</td></tr><tr><td><strong>credits</strong>（积分）</td><td>生成视频时扣的额度</td><td>决定你这段时间能做多少镜头</td></tr><tr><td><strong>Tools</strong></td><td>用自然语言描述、由 Flow 写代码生成的小工具</td><td>字幕条、改画幅这类重复活</td></tr><tr><td><strong>Agent</strong></td><td>提示词框里的对话式助手</td><td>帮你写提示词、列分镜、批量出候选</td></tr></tbody></table><p>几个容易混的，展开说。</p><h3 id="project-与-asset" tabindex="-1">project 与 asset <a class="header-anchor" href="#project-与-asset" aria-label="Permalink to &quot;project 与 asset&quot;">​</a></h3><p>新建项目点是 <strong>+ New project</strong>。左侧栏可以按类型找素材：All media、Images、Videos、Characters、Scenes、Uploads。素材可以拖进 <strong>Collection</strong>（像文件夹，可以嵌套）。</p><h3 id="generation-与-take" tabindex="-1">generation 与 take <a class="header-anchor" href="#generation-与-take" aria-label="Permalink to &quot;generation 与 take&quot;">​</a></h3><p>官方博客用过 take 这个词（「the first take isn&#39;t the final one」），但帮助中心的步骤里用的是 output（<code>Number of outputs you want</code>）。额度页专门强调了一句：「The Google Flow/AI credit costs below are per generation, not per request. Some product features will create multiple generations per request. For example, in Google Flow, you can make a single request that may generate 2 videos.」也就是说，一次要 2 个候选，就是 2 份积分。</p><h3 id="frame" tabindex="-1">frame <a class="header-anchor" href="#frame" aria-label="Permalink to &quot;frame&quot;">​</a></h3><p>首帧的界面文字是 <strong>+ Add start frame.</strong>，尾帧是 <strong>+ Add end frame.</strong>。你还可以从一段视频里取帧：暂停在某一帧，悬停后点 <strong>Save frame</strong>。</p><h3 id="ingredients-与-character" tabindex="-1">ingredients 与 character <a class="header-anchor" href="#ingredients-与-character" aria-label="Permalink to &quot;ingredients 与 character&quot;">​</a></h3><p>官方对 ingredients 的说明：「You can consistently use the same images for your character and key objects from one clip to the next with the use of ingredients.」</p><p>官方对 character 的说明：「You can bundle specific visual and audio references into a single, reusable character. Your character&#39;s face, clothing, and voice remain strictly consistent across multiple generations without needing to upload the same images every time.」</p><p>区别：ingredients 是<strong>每次生成时</strong>带上的参考；character 是<strong>建一次、反复引用</strong>的打包参考。提示词里输入 <code>@</code> 加角色名就能引用。</p><h3 id="scenebuilder、extend-与-jump-to" tabindex="-1">Scenebuilder、Extend 与 Jump to <a class="header-anchor" href="#scenebuilder、extend-与-jump-to" aria-label="Permalink to &quot;Scenebuilder、Extend 与 Jump to&quot;">​</a></h3><p>官方列的 Scenebuilder 能力：排列多个片段、调整顺序、用手柄修剪每个片段的首尾、预览整条序列、下载 scene。官方博客把它叫「your in-Flow storyboard, where you assemble individual clips into a complete narrative」。</p><p>官方对 Extend 的说明：「If you need a scene to be longer, you can create more footage and add it to the end of your original clip.」</p><p>Jump to 只有官方博客给过定义（2025-06-25）：「Transition a character or object to a completely new setting while preserving their appearance from the previous shot.」</p><h3 id="aspect-ratio-与-resolution" tabindex="-1">aspect ratio 与 resolution <a class="header-anchor" href="#aspect-ratio-与-resolution" aria-label="Permalink to &quot;aspect ratio 与 resolution&quot;">​</a></h3><p>帮助中心的模型页对每种模式都写「Both aspect ratios」，没有点名是哪两种。Veo 3.1 Lite 的官方发布文写该模型「offers flexible framing for landscape (16:9) and portrait (9:16) ratios」。</p><p>分辨率方面，Omni Flash 可以在 360p 出草稿，官方写它的积分是 720p 的三分之一。订阅用户可以把 360p 放大到 1080p，Ultra 订阅者可到 4K。</p><h3 id="tools-与-agent" tabindex="-1">Tools 与 Agent <a class="header-anchor" href="#tools-与-agent" aria-label="Permalink to &quot;Tools 与 Agent&quot;">​</a></h3><ul><li><strong>Tools</strong>：官方定义是「Build custom, reusable tools and mini-apps using natural language in Google Flow」。Flow 自带一批 Google 提供的预设 Tools。</li><li><strong>Agent</strong>：官方定义是「a built-in creative collaborator」，通过自然对话帮你梳理想法、改提示词、引导生成流程。</li></ul><h2 id="它是怎么工作的" tabindex="-1">它是怎么工作的 <a class="header-anchor" href="#它是怎么工作的" aria-label="Permalink to &quot;它是怎么工作的&quot;">​</a></h2><p>带着这个问题看下一张图：我输入的一句话、一张参考图，分别被哪个模型接手，最后怎么变成时间线上的一个片段？</p>',52)),l(o,{src:"/diagrams/google-flow-pipeline.svg",alt:"这张图从左到右分四段，回答一个问题：你输入的一句话、一张参考图，分别被哪个模型接手，最后怎么变成时间线上的一个片段。第一段是输入，有三样：文字提示、参考帧（start frame 与 end frame）、参考素材（角色、场景、物件）。第二段是模型。视频模型有两个，Gemini Omni 的 Omni Flash 与 Veo 3.1 的 Veo 3.1 Lite，负责视频生成、视频编辑与对话式迭代，每次生成都消耗积分，按秒或按次计算。图片模型是 Nano Banana 系列（Pro、2.1、2 Lite），负责图片生成与编辑，不消耗积分，走每日上限。第三段是产出：视频模型产出候选片段，图片模型产出图片。第四段是成片，也就是 Scenebuilder 的时间线。连线有六组。第一，文字提示直接进入视频模型。第二，参考帧和参考素材可以随同一次生成一起进入视频模型。第三，视频模型产出候选片段，图片模型产出图片。第四，从候选片段到 Scenebuilder 的箭头标着 Add to Scene，只有你挑中的候选才进入时间线，没挑中的不进入。第五，底部一条向左的虚线从产出的图片回到输入：生成的图片可以再当作后续视频生成的 start frame、end frame 或 ingredient。第六，模型层与 Scenebuilder 之间顶部的双向虚线是 Extend：从已有片段的末尾回到视频模型，生成续接片段后再回到时间线。Scenebuilder 内部，片段按顺序排列，可以拖动调整顺序，可以修剪首尾。本图省略了每个生成模式各自支持哪些模型的对照，因为同一个生成模式往往有多个模型都支持，所以输入到模型之间没有画成一对一；也省略了具体的积分数字、API 调用路径，以及积分体系分开的 Flow Music。",width:1080}),t[1]||(t[1]=e(`<blockquote><p><strong>图的依据：</strong> 四段的划分与各段对象来自帮助中心的<a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">创建视频</a>、<a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">编辑与搭建场景</a>和<a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">额度与单次消耗</a>三篇；模型名以<a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">官方模型页</a>为准（截至 2026-11-24）。图中保留了四段的对象、六组连线的方向，以及「积分只在视频模型这一层扣」；省略了每个生成模式各自支持哪些模型（同一个模式往往有多个模型支持，所以输入到模型之间没有画成一对一）、具体的积分数字、API 调用路径，以及积分体系分开的 Flow Music。实线是一次生成的主流程，虚线是回流与 Extend。</p></blockquote><p>图里有四个关系要记住：</p><ol><li><strong>输入决定走哪条路</strong>。只有文字，就直接交给视频模型。有参考图，它可以作为帧或参考素材，随同一次生成一起进入视频模型。</li><li><strong>图片是视频的原料</strong>。Nano Banana 生成的图，可以直接当后续视频生成的 ingredient、start frame 或 end frame。官方说明这些图片模型是用来「create frames and ingredients for your projects」的；从视频里取出的帧同样可用。</li><li><strong>模型不止一个，积分在模型这一层扣</strong>。视频由 Omni Flash 1.2 或 Veo 3.1 Lite 生成，扣积分；图片由 Nano Banana 系列生成，不扣积分。</li><li><strong>成片在 Scenebuilder 里成形</strong>。每次生成的候选片段先落在项目里，你挑中的才进时间线。</li></ol><h2 id="_10-分钟做出第一段视频" tabindex="-1">10 分钟做出第一段视频 <a class="header-anchor" href="#_10-分钟做出第一段视频" aria-label="Permalink to &quot;10 分钟做出第一段视频&quot;">​</a></h2><p>目标：从零做出一段 8 秒、720p 的视频并下载。按官方额度页折算，这一步花 <strong>24 积分</strong>（Omni Flash 1.2 的 720p 是每秒 3 积分）。当天的 50 积分够用。</p><h3 id="第-1-步-打开-flow-新建项目" tabindex="-1">第 1 步：打开 Flow，新建项目 <a class="header-anchor" href="#第-1-步-打开-flow-新建项目" aria-label="Permalink to &quot;第 1 步：打开 Flow，新建项目&quot;">​</a></h3><ul><li><strong>做什么</strong>：用 Chrome 或 Edge 打开 <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">Flow</a>，用你的 Google 账号登录（年龄、地区、积分都认账号），然后点 <strong>+ New project</strong>。</li><li><strong>会看到什么</strong>：一个空项目和一个提示词框。</li><li><strong>为什么</strong>：素材按项目存放。第一次用，不需要先建角色，也不需要上传参考图。</li></ul><h3 id="第-2-步-写一句提示词" tabindex="-1">第 2 步：写一句提示词 <a class="header-anchor" href="#第-2-步-写一句提示词" aria-label="Permalink to &quot;第 2 步：写一句提示词&quot;">​</a></h3><ul><li><strong>做什么</strong>：在提示词框里用英文描述场景。官方要求写清五样：「Be specific about the subject, action, environment, lighting, and style.」下面是本站写的示例，不是官方原文：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A slow wide shot of a dark studio desk at night. A slim laptop in the center</span></span>
<span class="line"><span>shows a plain dark dashboard with soft blue charts. A warm desk lamp on the</span></span>
<span class="line"><span>left lights the keyboard; the rest of the room falls into soft shadow. Fine</span></span>
<span class="line"><span>dust drifts in the light. The camera pushes in very slowly. No people, no text.</span></span></code></pre></div><ul><li><strong>会看到什么</strong>：提示词框里是你的文字。</li><li><strong>为什么</strong>：这是 Text to video 模式，只要一句话就能起步。</li></ul><h3 id="第-3-步-切到视频-选参数" tabindex="-1">第 3 步：切到视频，选参数 <a class="header-anchor" href="#第-3-步-切到视频-选参数" aria-label="Permalink to &quot;第 3 步：切到视频，选参数&quot;">​</a></h3><ul><li><strong>做什么</strong>：点模型名，点 <strong>Video</strong>，然后选四项：<strong>Aspect ratio</strong>、<strong>Number of outputs you want</strong>（第一次选 1）、<strong>The model you want to use</strong>（选 Omni Flash 1.2）、<strong>Generation length</strong>（选 8 秒）。</li><li><strong>会看到什么</strong>：提示词框里出现这四项视频设置。</li><li><strong>为什么</strong>：官方写「By default, Google Flow sets the model to Nano Banana Pro」，默认是图片模型，不切的话生成的是一张图。候选数量翻倍，扣分也翻倍。</li></ul><h3 id="第-4-步-生成-等结果" tabindex="-1">第 4 步：生成，等结果 <a class="header-anchor" href="#第-4-步-生成-等结果" aria-label="Permalink to &quot;第 4 步：生成，等结果&quot;">​</a></h3><ul><li><strong>做什么</strong>：点 <strong>Generate</strong>。</li><li><strong>会看到什么</strong>：结果以一个个独立的卡片出现在项目网格里（官方：「your generations now appear as individual tiles」）。等待期间卡片可能显示 <strong>Pending</strong>。</li><li><strong>为什么</strong>：先看一眼生成的样子，再决定要不要继续。</li><li><strong>卡住时</strong>：Pending 或报错卡片一直在，就看右上角的系统通知。官方说明，因为政策或积分限制而失败的生成，需要手动重试或删除。</li></ul><h3 id="第-5-步-挑一个留下" tabindex="-1">第 5 步：挑一个留下 <a class="header-anchor" href="#第-5-步-挑一个留下" aria-label="Permalink to &quot;第 5 步：挑一个留下&quot;">​</a></h3><ul><li><strong>做什么</strong>：满意就留着。第一次生成的结果本身就在项目里，帮助中心没有为它设单独的保存按钮。</li><li><strong>会看到什么</strong>：左侧栏选 <strong>Videos</strong>，能找到这段视频。</li><li><strong>为什么</strong>：<strong>Save to Project</strong> 用在另一种情况。你编辑过这段视频，想把某个旧版本留下来：点开视频，右侧 <strong>History</strong> 面板里悬停在版本上，点 <strong>Save to Project</strong>。官方说明，旧版本要进 Scenebuilder，得先保存。</li></ul><h3 id="第-6-步-下载" tabindex="-1">第 6 步：下载 <a class="header-anchor" href="#第-6-步-下载" aria-label="Permalink to &quot;第 6 步：下载&quot;">​</a></h3><ul><li><strong>做什么</strong>：鼠标悬停在素材上，点 <strong>More</strong>，再点 <strong>Download</strong>，选文件类型。想要 GIF 就选 <strong>270p</strong>。</li><li><strong>会看到什么</strong>：浏览器下载一个视频文件或 GIF。</li><li><strong>为什么</strong>：成片要进你的网页或汇报材料，下载是离开 Flow 的出口。</li></ul><p><strong>这次花了多少</strong>：回到右上角，点头像，头像下方是剩余积分，8 秒 720p 应该少了 24 分。想更省有两个办法：改用 Veo 3.1 Lite，一次生成是 10 分（非 Ultra）；或把 Omni Flash 1.2 的分辨率降到 360p，8 秒是 8 分。不满意时先改提示词，不要连着重试。重试就是再发起一次生成，照常扣分。</p><h2 id="各生成模式怎么用" tabindex="-1">各生成模式怎么用 <a class="header-anchor" href="#各生成模式怎么用" aria-label="Permalink to &quot;各生成模式怎么用&quot;">​</a></h2><p><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro 权益页</a> 列的模式是 Text to video、Ingredients to video、Frames to video、Text to image、Image to image。帮助中心的模型页另列 Video to Video editing 与 Extend videos (Omni Extend)。落地页用的是 Video Extension、Video-to-video editing 这两个写法。本页的小节标题沿用帮助中心的叫法。</p><p>先看一张总表，再逐个讲。内容来自 <a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">Learn about Google Flow models &amp; supported features</a>，截至 2026-11-24。</p><table tabindex="0"><thead><tr><th>模式</th><th>你手里有</th><th>Omni Flash 1.2</th><th>Veo 3.1 Lite</th></tr></thead><tbody><tr><td>Text to video</td><td>一句描述</td><td>支持，3 到 10 秒（订阅后到 15 秒）</td><td>支持，4、6、8 秒</td></tr><tr><td>Frames to video</td><td>首帧，或首尾两帧</td><td>支持，3 到 10 秒；仅网页版</td><td>支持；只有首帧、首尾两帧都可以</td></tr><tr><td>Ingredients to video</td><td>角色或物件的参考图</td><td>支持，3 到 10 秒</td><td>支持，仅 8 秒</td></tr><tr><td>Video to video</td><td>一段现成视频</td><td>支持，3 到 10 秒</td><td>不支持</td></tr><tr><td>Video extension</td><td>一段生成好的视频</td><td>支持，续 3 到 10 秒；需订阅；仅网页版</td><td>不支持</td></tr></tbody></table><p>Veo 3.1 Fast、Veo 3.1 Quality、Omni Flash 1.1 将于 <strong>2026-12-05 退役</strong>。官方建议新项目直接用 Omni Flash 1.2 或 Veo 3.1 Lite。</p><h3 id="text-to-video" tabindex="-1">Text to video <a class="header-anchor" href="#text-to-video" aria-label="Permalink to &quot;Text to video&quot;">​</a></h3><ul><li><strong>适合</strong>：从零起一个镜头，手上没有任何参考。</li><li><strong>准备</strong>：一句写清主体、动作、环境、光线、风格的英文描述。</li><li><strong>操作</strong>：见上一节第 2 到第 4 步。</li><li><strong>提示词怎么写</strong>：见本节末尾的「提示词怎么写」。</li><li><strong>常见失败</strong>：一次出了好几个候选，积分成倍扣。把 <strong>Number of outputs you want</strong> 设为 1。</li></ul><h3 id="frames-to-video" tabindex="-1">Frames to video <a class="header-anchor" href="#frames-to-video" aria-label="Permalink to &quot;Frames to video&quot;">​</a></h3><ul><li><strong>适合</strong>：手里有一张图（设计稿、截图、上一段的某一帧），想让它动起来；或者想同时控制一段视频的开头和结尾。</li><li><strong>准备</strong>：一张图做首帧；要同时控制结尾，再备一张做尾帧。官方提醒：「Product feature availability may differ by country/region of use. Certain image types may not be supported.」</li><li><strong>操作</strong>（官方步骤）： <ol><li>在项目的提示词框里点模型名。</li><li>点 <strong>Video</strong>，再点 <strong>Frames</strong>。</li><li>把图片拖到 <strong>+ Add start frame.</strong>；要尾帧，把另一张拖到 <strong>+ Add end frame.</strong></li><li>在提示词里描述两帧之间发生的动作或转场。</li><li>选视频参数，点 <strong>Generate</strong>。</li></ol></li><li><strong>提示词怎么写</strong>：重点写「怎么变」，不要复述图里已有的静态内容。示例见「产品演示」模板。</li><li><strong>常见失败</strong>：在手机应用里找不到 Frames。Omni Flash 1.2 的 Frames to Video 目前只在网页版提供。</li></ul><h3 id="ingredients-to-video" tabindex="-1">Ingredients to video <a class="header-anchor" href="#ingredients-to-video" aria-label="Permalink to &quot;Ingredients to video&quot;">​</a></h3><ul><li><strong>适合</strong>：多个镜头里要用同一个人、同一个物件、同一个场景。</li><li><strong>准备</strong>：参考图。官方建议主体或产品的参考图用<strong>纯色或抠好背景</strong>的图（「provide subject or product references on a plain or segmented background」）；场景与风格参考图里不要混进别的人物。</li><li><strong>操作</strong>（官方步骤）： <ol><li>在提示词框里点模型名。</li><li>点 <strong>Video</strong>，再点 <strong>Ingredients</strong>。</li><li>加参考素材，四种方式任选其一：从设备把参考图或参考视频拖进 Flow；在提示词框里输入 <code>@</code> 加素材名，引用项目里已有的素材；点 <strong>Add</strong> 选项目里的素材；点 <strong>Add</strong>，再点 <strong>Upload media</strong> 上传文件。</li><li>在提示词里写明每份参考素材怎么用。官方示例：参考素材是一位女士、一盏熔岩灯、一条雾蒙蒙的街，提示词是 <code>The woman, whose torso is the lava lamp, walks down the foggy street</code>。</li><li>选视频参数，点 <strong>Generate</strong>。</li></ol></li><li><strong>提示词怎么写</strong>：文字要配合参考图，不能互相矛盾，并且要点到你给的素材。官方：「Your text prompt should complement, not contradict, your visual inputs.」</li><li><strong>常见失败</strong>： <ul><li>用 Veo 3.1 Lite 时选了 8 秒以外的长度。该模型下 Ingredients 只支持 8 秒。</li><li>加了声音参考却报错。官方：「You can add voice references only to video generations that use ingredients.」入口在 Omni Flash 模型下的 <strong>Add</strong>、<strong>Voices</strong>。</li><li>角色还是变了。改用 Character，见下一节。</li></ul></li></ul><h3 id="text-to-image" tabindex="-1">Text to image <a class="header-anchor" href="#text-to-image" aria-label="Permalink to &quot;Text to image&quot;">​</a></h3><ul><li><strong>适合</strong>：先出关键静帧，定角色、定场景、定构图，再拿去做视频的帧或参考素材。</li><li><strong>准备</strong>：一句图片描述。</li><li><strong>操作</strong>（官方步骤）：进项目，点模型名，点 <strong>Image</strong>，选 <strong>Image aspect ratio</strong>、<strong>Number of outputs you want</strong> 和模型，写提示词，可选加 ingredients，点 <strong>Generate</strong>。</li><li><strong>提示词怎么写</strong>：官方只要求「describes the image you want to create in detail」。</li><li><strong>常见失败</strong>：以为出图花积分。官方：「Generating and upscaling images in Google Flow does not currently use your monthly Google Flow credits or AI credits.」图片走的是每日上限，见后文「额度」。</li></ul><h3 id="image-to-image" tabindex="-1">Image to image <a class="header-anchor" href="#image-to-image" aria-label="Permalink to &quot;Image to image&quot;">​</a></h3><ul><li><strong>适合</strong>：手上已有一张图，要换背景、换风格或裁切。</li><li><strong>准备</strong>：项目里的那张图。</li><li><strong>操作</strong>，两条官方路径： <ol><li>对话式改图。打开 <strong>Agent</strong>，把图片拖进提示词框（可一次拖多张），写要改什么，点 <strong>Generate</strong>。官方示例提示词：<code>Make these black and white.</code> 改动自动存进该素材的版本栈。</li><li>裁切。点开图片，左侧点 <strong>Crop</strong>，选裁切范围，点 <strong>Crop</strong>。</li></ol></li><li><strong>想引用项目里的另一张图</strong>：悬停在那张图上，点 <strong>More</strong>，再点 <strong>Add to prompt</strong>。</li><li><strong>常见失败</strong>：改完找不到旧图。原图没丢，右侧 <strong>History</strong> 面板里有全部历史版本和当时的提示词。</li></ul><h3 id="video-to-video" tabindex="-1">Video to video <a class="header-anchor" href="#video-to-video" aria-label="Permalink to &quot;Video to video&quot;">​</a></h3><ul><li><strong>适合</strong>：手里有一段拍好的或生成好的视频，要改光线、加东西、换背景。</li><li><strong>准备</strong>：最长 60 秒、最大 1 GB 的 <code>.mov</code>、<code>.mp4</code>、<code>.avi</code> 或 <code>.wmv</code> 文件。超过 30 秒的，必须在 Flow 里裁到 30 秒以内。</li><li><strong>操作</strong>（官方三步）： <ol><li>把视频模型设为 Omni Flash 1.2。打开提示词框底部的生成设置，点 <strong>Video</strong>，点视频模型，选 <strong>Omni Flash 1.2</strong>。</li><li>上传、拖入或选中视频。官方说明 Flow 会自动处理、转格式并做安全检查。</li><li>点要编辑的视频，在裁剪窗口里选最多 10 秒的一段（Plus / Pro / Ultra 订阅者最多 15 秒），写提示词，可选加 ingredients，点 <strong>Generate</strong>。之后还能追加提示词或 ingredients，最多 3 轮对话不丢上下文。</li></ol></li><li><strong>提示词怎么写</strong>：只写改什么，其余保留。官方示例：<code>Change the lighting to a cinematic sunset</code>、<code>Add a text overlay that says &#39;Coming Soon&#39;</code>。</li><li><strong>常见失败</strong>： <ul><li>提示地区不支持。官方写该功能「only available in certain countries」。</li><li>改不了人物说的话。官方在所有地区都不支持编辑或生成上传视频里人物说的话，改台词、加对白、配音都不行。要让人物开口，用提示词重新生成一段。</li><li>扣分比预想多。官方：「Edits cost the same credits per second as standard generations.」</li></ul></li></ul><h3 id="video-extension" tabindex="-1">Video extension <a class="header-anchor" href="#video-extension" aria-label="Permalink to &quot;Video extension&quot;">​</a></h3><ul><li><strong>适合</strong>：一个镜头很好，但太短。</li><li><strong>准备</strong>：Google AI Plus、Pro 或 Ultra 订阅；一段要延长的视频；可选最多 3 张参考图。</li><li><strong>操作</strong>（官方步骤）：进项目，点要延长的视频片段，底部点 <strong>Extend</strong>，选延长时长，在提示词框里描述动作如何继续，可加最多 3 张图片参考来保持角色与环境一致，点 <strong>Generate</strong>。</li><li><strong>提示词怎么写</strong>：写接下来的动作。官方博客解释过原理：「It analyzes the final frames and continues the action」。</li><li><strong>常见失败</strong>： <ul><li>按钮用不了。官方：「This feature is only available to Google AI Plus, Pro &amp; Ultra subscribers on the Omni Flash 1.2 model.」Veo Extend 已于 2026-11-05 退役。</li><li>延长后的片段不能再做 insert、remove、camera 这类编辑。</li><li>扣分按新增的秒数算，360p 每秒 1 分，720p 每秒 3 分。</li></ul></li></ul><h3 id="提示词怎么写-官方原则" tabindex="-1">提示词怎么写：官方原则 <a class="header-anchor" href="#提示词怎么写-官方原则" aria-label="Permalink to &quot;提示词怎么写：官方原则&quot;">​</a></h3><p>帮助中心 <a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos in Google Flow</a> 的「Best practices &amp; advanced tips when generating in Google Flow」一节列了三条：</p><ol><li><strong>Prepare clean ingredients</strong>。主体或产品的参考图用纯色或抠好背景；场景与风格参考图里不要有额外的人物，除非你就是想要。</li><li><strong>Avoid conflicting guidance</strong>。文字提示词要补充你给的图，不能否定它；提示词要点到你给的帧或参考素材；所有参考图的观感统一，模型更容易把它们融合在一起。</li><li><strong>Iterate with Gemini</strong>。把提示词、图片甚至视频发给 Gemini，让它改写提示词、发散想法。</li></ol><p>官方博客 <a href="https://blog.google/innovation-and-ai/products/flow-video-tips/" target="_blank" rel="noreferrer">5 tips for getting started with Flow</a>（2025-06-25）补了提示词里该有的要素：</p><ul><li><strong>Subject and action</strong>：谁或什么，在做什么。</li><li><strong>Composition and camera motion</strong>：用 <code>wide shot</code>、<code>close-up</code> 定景别，用 <code>tracking shot</code>、<code>aerial view</code> 定运镜。</li><li><strong>Location and lighting</strong>：不要只写「一个房间」，写光从哪来、什么东西落在影子里。</li><li><strong>Alternative styles</strong>：可以指定 <code>stop motion</code>、<code>clay animation</code> 这类风格。</li><li>让 Gemini 帮你写多个互相衔接的镜头时，要明确让它把前面提示词里的关键细节全部重复一遍。</li></ul><h3 id="提示词怎么写-三个模板" tabindex="-1">提示词怎么写：三个模板 <a class="header-anchor" href="#提示词怎么写-三个模板" aria-label="Permalink to &quot;提示词怎么写：三个模板&quot;">​</a></h3><p>下面三段都是<strong>本站写的示例</strong>，不是官方原文。结构相同：主体、动作、环境、光线、风格、排除项。按每段下面的表格逐项替换。</p><p><strong>模板一：落地页宣传片</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A slow wide shot of a dark studio desk at night. A slim laptop in the center</span></span>
<span class="line"><span>shows a plain dark dashboard with soft blue charts. A warm desk lamp on the</span></span>
<span class="line"><span>left lights the keyboard; the rest of the room falls into soft shadow. Fine</span></span>
<span class="line"><span>dust drifts in the light. The camera pushes in very slowly. No people, no text.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>对应的文字</th><th>作用</th></tr></thead><tbody><tr><td>景别与运镜</td><td><code>A slow wide shot</code>、<code>The camera pushes in very slowly</code></td><td>对应官方的 Composition and camera motion；运动越慢，越适合当背景</td></tr><tr><td>主体</td><td><code>A slim laptop in the center shows a plain dark dashboard</code></td><td>对应 Subject；界面只给轮廓，不指望模型画出你的真实产品</td></tr><tr><td>环境、光线与风格</td><td><code>dark studio desk at night</code>、<code>A warm desk lamp on the left</code>、<code>Fine dust drifts in the light</code></td><td>对应 Location and lighting；一个光源带出夜景风格，飘尘给静止画面加一点动势</td></tr><tr><td>排除项</td><td><code>No people, no text.</code></td><td>背景视频上还要叠你自己的文案，画面里不要再出现字</td></tr></tbody></table><p><strong>模板二：产品演示</strong>（配 Frames to video，把真实截图设为首帧）</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Start from the uploaded screenshot of a web app dashboard. Keep the layout,</span></span>
<span class="line"><span>colors and every UI element exactly as they are. A cursor moves to the top</span></span>
<span class="line"><span>right button, clicks it, and a dropdown menu opens with a soft fade. The page</span></span>
<span class="line"><span>stays sharp and still apart from that one interaction. Slow, smooth motion.</span></span>
<span class="line"><span>No new text, no camera movement.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>对应的文字</th><th>作用</th></tr></thead><tbody><tr><td>锚定参考图</td><td><code>Start from the uploaded screenshot</code></td><td>对应官方的「提示词要点到你给的帧」</td></tr><tr><td>保护项</td><td><code>Keep the layout, colors and every UI element exactly as they are</code></td><td>防止模型重画界面；对应「文字不要与参考图冲突」</td></tr><tr><td>动作</td><td><code>A cursor moves to the top right button, clicks it</code></td><td>一段只演一个操作，对应 Subject and action</td></tr><tr><td>排除项</td><td><code>No new text, no camera movement.</code></td><td>限制变化范围，减少走样</td></tr></tbody></table><p><strong>模板三：功能示意</strong>（抽象动效，适合讲流程）</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Three rounded rectangular cards float in a row on a soft light gray</span></span>
<span class="line"><span>background. A small blue dot travels from the first card to the second, then</span></span>
<span class="line"><span>to the third, leaving a thin glowing line behind it. Each card lifts slightly</span></span>
<span class="line"><span>when the dot arrives. Flat, clean motion graphics, soft shadows, gentle</span></span>
<span class="line"><span>easing. No text.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>对应的文字</th><th>作用</th></tr></thead><tbody><tr><td>主体</td><td><code>Three rounded rectangular cards float in a row</code></td><td>用抽象图形代表你功能里的三个对象</td></tr><tr><td>动作</td><td><code>A small blue dot travels from the first card to the second</code></td><td>讲清先后顺序</td></tr><tr><td>风格</td><td><code>Flat, clean motion graphics, soft shadows, gentle easing</code></td><td>对应 Alternative styles；动效风格与前端界面更接近</td></tr><tr><td>排除项</td><td><code>No text.</code></td><td>文案与数字用 HTML 叠加，方便修改与本地化</td></tr></tbody></table><h2 id="把多段素材接成一部成片" tabindex="-1">把多段素材接成一部成片 <a class="header-anchor" href="#把多段素材接成一部成片" aria-label="Permalink to &quot;把多段素材接成一部成片&quot;">​</a></h2><p>一次生成只有几秒到十几秒：Omni Flash 1.2 是 3 到 10 秒，订阅后到 15 秒；Veo 3.1 Lite 是 4、6、8 秒。成片要把多个镜头接起来，还要让角色和场景在镜头之间对得上。这是 Flow 相对「一次生成一段」的核心价值。</p><p>下面用一个例子走完整条路：同一个角色出现在三个镜头里，每个 8 秒。</p><h3 id="第-1-步-固定角色与场景" tabindex="-1">第 1 步：固定角色与场景 <a class="header-anchor" href="#第-1-步-固定角色与场景" aria-label="Permalink to &quot;第 1 步：固定角色与场景&quot;">​</a></h3><p>三种官方机制，按需要选：</p><table tabindex="0"><thead><tr><th>机制</th><th>怎么建</th><th>怎么引用</th><th>适合</th></tr></thead><tbody><tr><td><strong>Character</strong></td><td>左侧选 <strong>Characters</strong>；已有角色时点 <strong>New Character</strong>。写描述，上传或生成 1 到 2 张图（至少 1 张才能用），点 <strong>Generate</strong>；再起名、选声音，点 <strong>Done</strong></td><td>提示词里输入 <code>@</code> 加角色名，例如 <code>@CaptainZoro walking through a futuristic city</code></td><td>全片反复出现的角色</td></tr><tr><td><strong>ingredients</strong></td><td>每次生成时把参考图拖进提示词框</td><td>在提示词里写明每份参考怎么用</td><td>只在某几个镜头出现的物件或场景</td></tr><tr><td><strong>Avatar</strong></td><td>右上角头像菜单里点 <strong>Create avatar</strong>；在电脑上开始，用手机扫二维码完成</td><td>提示词里输入 <code>@me</code></td><td>出镜人是你自己</td></tr></tbody></table><p>Avatar 在欧洲经济区、英国、瑞士不可用。</p><h3 id="第-2-步-先出关键静帧" tabindex="-1">第 2 步：先出关键静帧 <a class="header-anchor" href="#第-2-步-先出关键静帧" aria-label="Permalink to &quot;第 2 步：先出关键静帧&quot;">​</a></h3><p>用 Text to image 把角色和场景的定妆图先出好。官方博客说过图片与视频的衔接方式：有了内建的 Nano Banana，你可以「create high-fidelity images and instantly use them as ingredients and frames for Veo video generations without ever leaving Flow」。图片不扣积分。</p><h3 id="第-3-步-逐个镜头生成" tabindex="-1">第 3 步：逐个镜头生成 <a class="header-anchor" href="#第-3-步-逐个镜头生成" aria-label="Permalink to &quot;第 3 步：逐个镜头生成&quot;">​</a></h3><p>每个镜头用 Ingredients to video 或 Frames to video 生成。先用 360p 看构图（每秒 1 分），满意了再用 720p 出正式版。</p><h3 id="第-4-步-让镜头之间接得上" tabindex="-1">第 4 步：让镜头之间接得上 <a class="header-anchor" href="#第-4-步-让镜头之间接得上" aria-label="Permalink to &quot;第 4 步：让镜头之间接得上&quot;">​</a></h3><ul><li><strong>上一镜的结尾当下一镜的开头</strong>。打开镜头 A，暂停在要接的那一帧，悬停后点 <strong>Save frame</strong>。官方说明存下来的帧可用于后续生成，当作 ingredient、start frame 或 end frame。再把它设成镜头 B 的 start frame。</li><li><strong>镜头太短</strong>。点片段，底部点 <strong>Extend</strong>，续 3 到 10 秒，可带最多 3 张参考图保持角色与环境一致。</li><li><strong>同一个角色换场景</strong>。官方博客对 <strong>Jump to</strong> 的定义见「核心概念」。当前帮助中心没有写它的入口，用之前先在你的界面里确认它还在。</li></ul><h3 id="第-5-步-在-scenebuilder-里排列" tabindex="-1">第 5 步：在 Scenebuilder 里排列 <a class="header-anchor" href="#第-5-步-在-scenebuilder-里排列" aria-label="Permalink to &quot;第 5 步：在 Scenebuilder 里排列&quot;">​</a></h3><ol><li>悬停在做好的片段上，点 <strong>More</strong>，再点 <strong>Add to Scene</strong>。</li><li>点开这个 scene（左侧栏的 <strong>Scenes</strong> 里能找到），拖动片段调整顺序。</li><li>拖两端的手柄，修剪每个片段的开头和结尾。</li><li>预览整条序列。</li><li>下载 scene。</li></ol><h3 id="第-6-步-带走成片" tabindex="-1">第 6 步：带走成片 <a class="header-anchor" href="#第-6-步-带走成片" aria-label="Permalink to &quot;第 6 步：带走成片&quot;">​</a></h3><p>下载 scene，得到一个视频文件。要发到 YouTube：单个片段可以在 Flow 里点 <strong>More</strong>、<strong>Publish to YouTube</strong> 直接发；Scenebuilder 的序列不行，官方要求先下载成单个文件，再经 YouTube Studio 上传。</p><h2 id="自定义-tools-与-agent" tabindex="-1">自定义 Tools 与 Agent <a class="header-anchor" href="#自定义-tools-与-agent" aria-label="Permalink to &quot;自定义 Tools 与 Agent&quot;">​</a></h2><h3 id="tools-用自然语言写一个小工具" tabindex="-1">Tools：用自然语言写一个小工具 <a class="header-anchor" href="#tools-用自然语言写一个小工具" aria-label="Permalink to &quot;Tools：用自然语言写一个小工具&quot;">​</a></h3><p><strong>是什么</strong>：你用一句话描述需求，Flow 写代码并搭出界面。官方举的例子是「Make an image filter app with a slider for grayscale and hue shift.」落地页列的用途有字幕叠层、改比例、分镜、shader。</p><p><strong>谁能用</strong>：官方写得很明确。</p><ul><li>使用预置的 Tools：所有用户。</li><li>创建与 remix：需要 Google AI Plus、Pro 或 Ultra 订阅。官方：「If you&#39;re not subscribed, you can still explore and use pre-built tools.」</li><li>平台：仅网页版与 PC。</li></ul><p><strong>怎么建一个最简单的 tool</strong>（官方步骤）：</p><ol><li>进项目，左侧点 <strong>Tools</strong>，再点 <strong>Create Tool</strong>。</li><li>在提示词框里描述你要的工具。本站示例，非官方原文：<code>A tool that adds a caption bar to the bottom of a clip, with an editable text field.</code></li><li>点 <strong>Generate</strong>。</li><li>检查界面。等 agent 构建完，点 <strong>Save</strong>。</li></ol><p><strong>建完之后</strong>：</p><ul><li><strong>改</strong>：打开 Tool，点 <strong>Edit</strong>，在右侧描述要怎么改代码，点 <strong>Generate</strong>。</li><li><strong>分享</strong>：右上角 <strong>Share</strong>，再点 <strong>Copy link</strong>。官方提醒：拿到链接的人都能看到这个 Tool 的代码、名称和缩略图。链接只分享生成链接时的版本，之后的修改不会同步。要停止分享，只能删除这个 Tool。</li><li><strong>Pin、Favorite、Remix tool</strong>：分别是固定到当前项目、全局可用、复制一份自己改。</li></ul><p><strong>扣分</strong>：Tool 生成的媒体照常扣 Flow 积分。官方说明，运行某个 Tool 可能扣分时，Flow 一定会显示警告横幅。创建 Tool 有每日数量上限，帮助中心没有为「创建」单列扣分。</p><h3 id="agent-提示词框里的对话式助手" tabindex="-1">Agent：提示词框里的对话式助手 <a class="header-anchor" href="#agent-提示词框里的对话式助手" aria-label="Permalink to &quot;Agent：提示词框里的对话式助手&quot;">​</a></h3><p><strong>是什么</strong>：官方称它为「a built-in creative collaborator」。落地页的描述是项目级创意搭档，帮你探索和迭代。官方博客补充，它由 Gemini 模型构建。</p><p><strong>能做什么</strong>（官方清单）：</p><ul><li><strong>Brainstorm and plan</strong>：列分镜、做情绪板、把笼统的想法变成可用的提示词。</li><li><strong>Generate new media</strong>：让它生成视频或图片，它会挑合适的模型。</li><li><strong>Edit assets directly</strong>：让它改项目里选中的素材。</li><li><strong>Batch generate</strong>：一次生成一个素材的多个变体。</li><li><strong>Organize your assets</strong>：重命名文件、把素材归进 Collection、删除不用的素材。</li></ul><p><strong>怎么用</strong>：</p><ol><li>进项目，在提示词框里点 <strong>Agent</strong> 打开。再点一次是关闭。</li><li>要展开侧边对话面板，点 <strong>Expand</strong>。</li><li>写你的要求。要带参考，把素材从设备或项目拖进提示词框，或点 <strong>Add</strong> 选择、上传。</li><li>点 <strong>Generate</strong>。</li></ol><p><strong>三个要知道的设置</strong>：</p><ul><li><strong>Confirm before generating</strong>。默认 Agent 在做任何会消耗积分的动作前先问你。官方提醒：选 <strong>Never</strong> 之后，它会替你生成并扣分，不再停下来确认。建议保持 <strong>Always</strong>。</li><li><strong>Agent Instructions</strong>。提示词框底部点 <strong>Agent Instructions</strong>、<strong>Add instruction</strong>，可以放一张参考图并写规则，让 Agent 在整个项目里表现一致。</li><li><strong>会话</strong>。对话自动存为 Sessions，按项目区分。侧边面板顶部点 <strong>Menu</strong> 可以打开、新建、重命名、删除会话。删除会话只清对话记录，生成的素材还在。</li></ul><p><strong>扣分</strong>：Agent 生成的媒体照常扣积分，并自动存进当前打开的项目。Agent 对话本身目前不扣积分，走的是每个套餐自己的每日查询上限。</p><h2 id="真实用例" tabindex="-1">真实用例 <a class="header-anchor" href="#真实用例" aria-label="Permalink to &quot;真实用例&quot;">​</a></h2><p>三个前端工程师最常见的场景。做法是本站根据官方步骤给的，不是官方用例。</p><table tabindex="0"><thead><tr><th>场景</th><th>用到的模式</th><th>预期产出</th></tr></thead><tbody><tr><td>落地页背景视频</td><td>Text to image 定调，Text to video 出片</td><td>一段 8 到 10 秒的 MP4，配几行 HTML</td></tr><tr><td>产品 demo 片段</td><td>Frames to video 为主，Scenebuilder 串联</td><td>一个 15 到 30 秒的 scene，下载成单个视频</td></tr><tr><td>给 PM 演示的动态分镜</td><td>Agent 列分镜，360p 草稿，Scenebuilder 串联</td><td>一个 3 到 5 镜头的 scene</td></tr></tbody></table><h3 id="落地页背景视频" tabindex="-1">落地页背景视频 <a class="header-anchor" href="#落地页背景视频" aria-label="Permalink to &quot;落地页背景视频&quot;">​</a></h3><ul><li><strong>要什么</strong>：一段循环播放、不抢文字的横幅背景。</li><li><strong>做法</strong>：用「提示词怎么写」的模板一生成 8 到 10 秒。提示词里排除人物与文字，标题和文案用 HTML 叠在视频上。订阅用户可以把成片放大到 1080p，1 到 10 秒的放大不扣积分。</li><li><strong>预期产出</strong>：一个 <code>.mp4</code> 文件，加下面这段标签。</li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 背景视频：静音才能自动播放；poster 在视频加载前先占位 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">video</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hero-bg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> autoplay</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> muted</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loop</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> playsinline</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> preload</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;metadata&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> poster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/hero-poster.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/hero.mp4&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;video/mp4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">video</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>两点提醒：</p><ul><li>帮助中心没有写 Flow 能生成首尾相接的循环视频。接缝处要自己看片确认。</li><li>片段可能带原生声音（项目设置里的 <strong>Return silent videos</strong> 打开后，所有视频生成为静音），所以网页里务必加 <code>muted</code>，否则浏览器的自动播放策略可能拦下它。</li></ul><h3 id="产品-demo-片段" tabindex="-1">产品 demo 片段 <a class="header-anchor" href="#产品-demo-片段" aria-label="Permalink to &quot;产品 demo 片段&quot;">​</a></h3><ul><li><strong>要什么</strong>：15 到 30 秒，演示一个功能的两三个操作。</li><li><strong>做法</strong>：把真实截图设为首帧，用模板二的方式让截图动起来。一段只演一个操作，几段在 Scenebuilder 里排起来。</li><li><strong>预期产出</strong>：一个 scene，下载成单个视频文件。</li><li><strong>要知道的边界</strong>：模型生成的界面是「画出来的」，不是你产品的真实录屏。给 PM 或团队内部演示够用。对外的官方 demo，建议用真实录屏，Flow 的片段只做开场与转场。</li></ul><h3 id="给-pm-演示的动态分镜" tabindex="-1">给 PM 演示的动态分镜 <a class="header-anchor" href="#给-pm-演示的动态分镜" aria-label="Permalink to &quot;给 PM 演示的动态分镜&quot;">​</a></h3><ul><li><strong>要什么</strong>：把一个功能的几个画面按顺序动起来，供评审讨论。</li><li><strong>做法</strong>：先让 Agent 列分镜，再把分镜逐条变成提示词。每个镜头先用 Omni Flash 1.2 的 360p 出草稿，每秒 1 分；4 个 8 秒镜头共 32 分。挑中的再放大，订阅用户 1 到 10 秒放大到 1080p 不扣积分。需要同一个角色贯穿时，先建 Character。</li><li><strong>预期产出</strong>：一个 3 到 5 镜头的 scene，外加一份可以照着实现的分镜提示词。</li></ul><h2 id="额度" tabindex="-1">额度 <a class="header-anchor" href="#额度" aria-label="Permalink to &quot;额度&quot;">​</a></h2><p>数字来自 <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Manage your Google Flow credits</a>，截至 2026-11-24，<strong>不是</strong>从第三方博客抄的。</p><table tabindex="0"><thead><tr><th>档位</th><th>Flow 积分</th></tr></thead><tbody><tr><td>无订阅</td><td><strong>每天 50</strong>（试用；当日未用完不结转）</td></tr><tr><td>AI Plus</td><td><strong>每月 200</strong>（另每天 50）</td></tr><tr><td>AI Pro</td><td><strong>每月 1,000</strong>（另每天 50）</td></tr><tr><td>AI Ultra $100（本站称 Ultra 5x）</td><td><strong>每月 10,000</strong>（另每天 50）</td></tr><tr><td>AI Ultra $200（本站称 Ultra 20x）</td><td><strong>每月 25,000</strong>（另每天 50）</td></tr></tbody></table><p>要点：</p><ul><li>订阅用户的月度积分是<strong>额外</strong>的。官方原文：「With or without a subscription, you receive 50 Google Flow credits per day. Subscribers receive extra Google Flow credits」。</li><li>付费档按<strong>计费周期</strong>刷新，未用完的月度积分<strong>不结转</strong>。</li><li>每日积分的刷新由当天第一次生成触发。官方的例子：8 月 12 日第一次用，下一批 50 分在 8 月 13 日可用。</li><li>用尽后，Plus / Pro / Ultra 可另购 AI credits 续用（日本除外）。同一笔 AI credits 也可用于 <a href="./antigravity.html">Antigravity</a>。</li><li>官方：「To generate content in Google Flow, you need to use Google Flow credits or AI credits.」积分按账号共享，换设备不换账本。</li><li>查余额：右上角点头像，头像下方是剩余积分。Plus / Pro / Ultra 还能看扣分明细与下次刷新日期。</li></ul><p>四档存储、模型倍率、Cloud 额度等<strong>整张订阅表只在</strong><a href="./gemini-cheatsheet.html#订阅层级">速查表</a>。</p><h3 id="各操作扣不扣积分" tabindex="-1">各操作扣不扣积分 <a class="header-anchor" href="#各操作扣不扣积分" aria-label="Permalink to &quot;各操作扣不扣积分&quot;">​</a></h3><p>官方提醒「Limits are subject to change at any time」。最新价格在提示词框右上角的 <strong>Settings</strong> 里看。</p><table tabindex="0"><thead><tr><th>操作</th><th>扣不扣</th><th>扣多少（截至 2026-11-24）</th></tr></thead><tbody><tr><td>用 Omni Flash 1.2 生成或编辑视频</td><td>扣</td><td>360p 每秒 1 分；720p 每秒 3 分。所有用户都可生成到 10 秒</td></tr><tr><td>用 Omni Flash 1.2 生成 11 到 15 秒</td><td>扣</td><td>仅订阅用户。超过 10 秒的部分，360p 每秒 2 分，720p 每秒 6 分</td></tr><tr><td>用 Veo 3.1 Lite 生成 4、6、8 秒</td><td>扣</td><td>每次 10 分；Ultra 订阅者每次 5 分</td></tr><tr><td>Veo 3.1 Lite 的 Lower Priority 模式</td><td>不扣</td><td>仅 Ultra 20x 订阅者与家庭组管理者</td></tr><tr><td>Omni Extend</td><td>扣</td><td>仅订阅用户。每新增 1 秒，360p 1 分，720p 3 分</td></tr><tr><td>把 360p 放大到 720p 或 1080p</td><td>1 到 10 秒不扣</td><td>仅订阅用户。超过 10 秒的部分每秒 1 分</td></tr><tr><td>放大到 4K</td><td>扣</td><td>仅 Ultra。1 到 10 秒固定 50 分；超过 10 秒的部分每秒 5 分</td></tr><tr><td>Veo 3.1 Quality 生成 8 秒（即将退役）</td><td>扣</td><td>所有用户每次 100 分</td></tr><tr><td>生成、放大图片</td><td>不扣</td><td>走每日上限，见下表</td></tr><tr><td>Agent 对话</td><td>不扣</td><td>每个套餐有每日查询上限；Agent 生成的媒体照常扣</td></tr><tr><td>创建 Tool</td><td>官方未单列</td><td>每天可创建的数量有上限；Tool 生成的媒体照常扣</td></tr><tr><td>生成失败，或触发安全过滤</td><td>不扣</td><td>生成开始时先扣，之后一小时内退回</td></tr><tr><td>重试</td><td>扣</td><td>依据官方「costs are per generation, not per request」推出，不是官方原句</td></tr><tr><td>保存版本、保存帧、下载、在 Scenebuilder 里排列</td><td>官方未列消耗</td><td>额度页没有为这几项写任何扣分</td></tr></tbody></table><p>图片的每日上限来自 <a href="https://support.google.com/flow/answer/16729550" target="_blank" rel="noreferrer">Create &amp; edit images in Flow</a>：</p><table tabindex="0"><thead><tr><th>模型或操作</th><th>无订阅</th><th>AI Plus 与 Pro</th><th>AI Ultra</th></tr></thead><tbody><tr><td>Nano Banana Pro</td><td>每天 20 张</td><td>每天 100 张</td><td>每天 500 张</td></tr><tr><td>Nano Banana 2.1 与 2 Lite（共用）</td><td>每天 400 张</td><td>每天 1,000 张</td><td>每天 1,000 张</td></tr><tr><td>2K 放大</td><td>每天 200 次</td><td>每天 200 次</td><td>每天 200 次</td></tr><tr><td>4K 放大</td><td>不可用</td><td>不可用</td><td>每天 200 次</td></tr></tbody></table><p>每日上限在你当天第一次用该模型后 24 小时重置。图片生成失败或被安全过滤拦下，不计入当日上限。</p><h2 id="何时用-什么时候不要用" tabindex="-1">何时用，什么时候不要用 <a class="header-anchor" href="#何时用-什么时候不要用" aria-label="Permalink to &quot;何时用，什么时候不要用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我要…</th><th>用</th><th>不要用 Flow</th></tr></thead><tbody><tr><td>落地页 / 宣传片 / 产品演示 <strong>视频</strong></td><td><strong>Flow</strong></td><td>Canvas 出的是能点的页面，不是成片</td></tr><tr><td>半小时内给产品经理一个 <strong>能点的原型</strong></td><td><a href="./canvas.html">Canvas</a></td><td>Flow 不做 DOM / 交互</td></tr><tr><td>把选定方案写进仓库</td><td><a href="./antigravity.html">Antigravity</a></td><td>Flow 不改代码、不出 PR</td></tr><tr><td>歌曲 / MV / 生成式配乐</td><td><a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">Flow Music</a>（积分与 Flow <strong>分开</strong>）</td><td>不要把 Flow 视频积分当成音乐积分</td></tr></tbody></table><p>Flow Music 那一行有官方依据：「Google Flow Music credits are separate from your Google AI credits.」</p><p>实用组合：Canvas 试三个交互方向，选定一个，交给 Antigravity 在工程里实现。需要对外讲这个功能时，再用 Flow 出 8 到 10 秒演示片。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>官方把它叫 <strong>AI creative studio</strong>：用自然语言做计划、生成、精修，底层是 Google 的生成式模型。</p><p>落地页当前列出三套模型：</p><table tabindex="0"><thead><tr><th>模型</th><th>官方一句话</th></tr></thead><tbody><tr><td><strong>Gemini Omni</strong></td><td>从任意输入参考（真实或生成）创建并编辑视频；强调世界理解、多模态与对话式编辑</td></tr><tr><td><strong>Nano Banana</strong></td><td>图像生成与精细编辑；强调主体一致性、文字渲染、推理</td></tr><tr><td><strong>Veo 3.1</strong></td><td>视频生成；强调物理、真实感、提示词遵循，带原生音频与扩展控制</td></tr></tbody></table><p>帮助中心用的是更具体的模型名，按家族对得上：</p><table tabindex="0"><thead><tr><th>家族（落地页的叫法）</th><th>帮助中心里的具体模型（截至 2026-11-24）</th><th>状态</th></tr></thead><tbody><tr><td>Gemini Omni</td><td>Omni Flash 1.2；Omni Flash 1.1</td><td>1.1 于 2026-12-05 退役</td></tr><tr><td>Veo 3.1</td><td>Veo 3.1 Lite；Veo 3.1 Fast；Veo 3.1 Quality</td><td>Fast 与 Quality 于 2026-12-05 退役</td></tr><tr><td>Nano Banana</td><td>Nano Banana Pro；Nano Banana 2.1；Nano Banana 2 Lite</td><td>图片模型，用来生成帧与参考素材</td></tr></tbody></table><p><strong>能做什么</strong>，来自 <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">产品落地页</a> 与 <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Pro 权益说明</a> 列出的能力：</p><ul><li><strong>生成模式</strong>：Text to video、Frames to video、Ingredients to video、Text to image、Image to image</li><li><strong>精修</strong>：Video Extension、Video-to-video editing、Scenebuilder</li><li><strong>角色</strong>：Characters、Avatars</li><li><strong>Agent</strong>：官方描述为项目级创意搭档，帮你探索和迭代</li><li><strong>自定义 Tools</strong>：用自然语言做工具（字幕叠层、改比例、分镜、shader），可分享 / remix。免费档只能<strong>使用</strong>已有 Tools；Plus 起才能<strong>创建</strong></li></ul><p><strong>产出带水印</strong>。官方：「All outputs generated in Google Flow using Veo, Omni, or Nano Banana include invisible SynthID watermarks.」可见水印由你控制：头像下拉菜单里的「Visible watermarking」开关。住在印度、韩国、越南且不是 Ultra 20x 的用户，会自动加可见水印。</p><p><strong>商用</strong>：官方答的是服务条款说了算，条款里写 Google 不会主张对生成内容的所有权。</p><p>它不在编码主线上。对位 Claude 家族里的 <a href="./../claude/claude-design.html">Claude Design</a>：Design 出可交接的界面原型，Flow 出可发布的影像。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><p>每条都注明官方依据。没有另注出处的，依据都来自帮助中心的 <a href="https://support.google.com/flow/answer/16353333" target="_blank" rel="noreferrer">Get started</a>、<a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">创建视频</a>、<a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">编辑与 Scenebuilder</a>、<a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">模型与支持功能</a>、<a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">额度</a>、<a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">可用地区</a>、<a href="https://support.google.com/flow/answer/17093911" target="_blank" rel="noreferrer">Agent</a> 七页。</p><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td>打不开，或提示所在地区不可用</td><td>中国大陆不在支持列表</td><td>查<a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">可用地区</a>。VPN <strong>不能</strong>绕过：官方写「VPNs will not enable access in unsupported regions」</td></tr><tr><td>开着 VPN，报「We noticed some unusual activity」</td><td>官方要求关掉 VPN 与代理</td><td>官方给的两步：过几分钟重试；停用 VPN 或代理</td></tr><tr><td>订了 AI Pro，还是进不去</td><td>Flow 不是在所有卖 AI Pro 的国家都开放</td><td>买之前先查支持列表。人在支持地区，联系 Google One 支持</td></tr><tr><td>没订阅，某段时间生成不了视频</td><td>高峰时段（约 14:00 到 17:00 UTC）限制非订阅用户</td><td>错开北京时间 22:00 到次日 01:00；这段时间仍可生成图片、用 Agent</td></tr><tr><td>提示积分不够</td><td>视频按秒或按次扣。Omni Flash 1.2 的 8 秒 720p 是 24 分</td><td>右上角头像下看余额。改用 360p 草稿，或换成每次 10 分的 Veo 3.1 Lite</td></tr><tr><td>生成失败了，余额却少了</td><td>官方：生成开始时就扣分；失败或触发安全过滤，积分一小时内退回</td><td>等一小时。余额与扣分记录可能晚一点才更新。仍然不对，联系 Google One 支持</td></tr><tr><td>报「Audio Generation Failed」</td><td>Veo 的音频质量不达标时，视频不会生成，积分退回</td><td>重试，或换提示词。宁可要无声视频：项目设置里打开 <strong>Return silent videos</strong>，这样照常出片、照常扣分</td></tr><tr><td>角色前后不一致</td><td>镜头之间没有带参考</td><td>建 Character 并用 <code>@名字</code> 引用，或每次都带 ingredients 与首尾帧。参考图用干净背景，各参考图风格统一</td></tr><tr><td>一次请求扣了好几份积分</td><td>费用按 generation 计，不按 request；一次要 2 个候选就是 2 份</td><td><strong>Number of outputs you want</strong> 设为 1。先用 360p 试，满意再出 720p</td></tr><tr><td>不满意就连着重试，积分很快没了</td><td>每次重试都是一次新生成</td><td>先改提示词。把提示词发给 Gemini 或 Flow 的 Agent 帮你改，对话本身不扣积分</td></tr><tr><td>用中文写提示词，效果不稳定</td><td>官方建议用英文提示词，其他语言的效果会因语言和复杂度而不同</td><td>提示词用英文写。可以让 Gemini 帮你翻译、改写</td></tr><tr><td>把 Flow 积分当成了 Flow Music 积分</td><td>官方：「Google Flow Music credits are separate from your Google AI credits.」</td><td>两本账分开算</td></tr><tr><td>选了某个功能，模型被自动换掉</td><td>当前模型不支持该功能，Flow 会建议切换到兼容模型</td><td>生成前在提示词框的设置里确认模型、分辨率和最新价格</td></tr><tr><td>想让上传视频里的人改口型、说新台词</td><td>官方在所有地区都不支持编辑或生成上传视频里人物说的话</td><td>用提示词重新生成一段新视频。画面、背景音、音乐、音效仍可编辑</td></tr><tr><td>生成名人，或编辑带未成年人的上传视频</td><td>官方在所有地区都不支持</td><td>换题材</td></tr><tr><td>报「You&#39;re requesting generations too quickly」</td><td>平台限流，零积分模型尤其明显</td><td>等一会儿再试</td></tr><tr><td>卡片一直是「Pending」</td><td>可能有系统通知没处理；政策或积分限制导致的失败要人工处理</td><td>看右上角的系统通知。手动重试，或删掉这张卡</td></tr><tr><td>加了声音参考，报错</td><td>声音参考只能用于带 ingredients 的视频生成</td><td>切到 Omni Flash，走 Video、Ingredients，再点 Add、Voices</td></tr><tr><td>Extend 用不了</td><td>仅订阅用户、仅 Omni Flash 1.2、仅网页版；Veo Extend 已于 2026-11-05 退役</td><td>三项都满足再试</td></tr><tr><td>下载的成片有可见水印</td><td>住在印度、韩国、越南且不是 Ultra 20x 时自动加；其他地区由开关决定</td><td>在头像下拉菜单里检查「Visible watermarking」。不可见的 SynthID 一直都在，官方要求不要移除</td></tr><tr><td>看到官方页面写「必须订阅才能用」</td><td>那是「Get started」页旧版的原话，2026-11-24 仍能从部分缓存读到</td><td>同日的实时页面与额度页一致：不订阅也能用基础的视频生成与编辑，每天 50 分</td></tr></tbody></table><h2 id="flow-sessions" tabindex="-1">Flow Sessions <a class="header-anchor" href="#flow-sessions" aria-label="Permalink to &quot;Flow Sessions&quot;">​</a></h2><p><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">落地页</a> 上的 <strong>Flow Sessions</strong> 是艺术家合作计划：邀请一小批创作者用 Flow 做激情项目、并与 Google 合作。<strong>不是日常产品</strong>，前端工程师不需要单独学，也不要把它写成教程。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想在自己的代码里调 Veo 或 Nano Banana，去 <a href="./ai-studio.html">AI Studio</a>。</li><li>想知道订哪一档，看 <a href="./google-pro.html">Google AI 订阅</a>。</li><li>想要能点的原型，看 <a href="./canvas.html">Canvas</a>。</li><li>Flow 在 Gemini 家族里的位置，看 <a href="./gemini-glossary.html">术语表</a>。</li><li>想看别人怎么写提示词，去 <a href="https://labs.google/flow/tv" target="_blank" rel="noreferrer">Flow TV</a>。官方说明：用屏幕底部的遥控器浏览频道，能看到每个片段背后的提示词。</li></ul><h2 id="官方资源与深入阅读" tabindex="-1">官方资源与深入阅读 <a class="header-anchor" href="#官方资源与深入阅读" aria-label="Permalink to &quot;官方资源与深入阅读&quot;">​</a></h2><p>帮助中心，每篇一句话：</p><ul><li><a href="https://support.google.com/flow" target="_blank" rel="noreferrer">Flow 帮助中心</a>：全部官方文章的目录。</li><li><a href="https://support.google.com/flow/answer/16353333" target="_blank" rel="noreferrer">Get started with Google Flow</a>：谁能用、怎么进、报错与水印的官方问答。</li><li><a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos in Google Flow</a>：三种视频生成方式、加帧、加参考素材、加声音的步骤，以及官方的提示词原则。</li><li><a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">Edit videos &amp; build scenes in Google Flow</a>：Extend、编辑现成视频、保存帧、Scenebuilder。</li><li><a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">Learn about Google Flow models &amp; supported features</a>：官方的模式与模型支持表、退役时间。</li><li><a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Manage your Google Flow credits</a>：额度、刷新规则、逐项消耗。</li><li><a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Where you can use Google Flow</a>：支持的语言与国家或地区，以及分地区的功能限制。</li><li><a href="https://support.google.com/flow/answer/16729550" target="_blank" rel="noreferrer">Create &amp; edit images in Flow</a>：图片的生成、编辑与每日上限。</li><li><a href="https://support.google.com/flow/answer/16935308" target="_blank" rel="noreferrer">Manage your Flow projects, assets &amp; collections</a>：项目、素材、Character、下载、分享、发布到 YouTube。</li><li><a href="https://support.google.com/flow/answer/17093911" target="_blank" rel="noreferrer">Use the Google Flow Agent</a>：Agent 的开关、会话、指令与默认设置。</li><li><a href="https://support.google.com/flow/answer/17104535" target="_blank" rel="noreferrer">Create &amp; manage Tools in Google Flow</a>：创建、编辑、分享 Tools。</li><li><a href="https://support.google.com/flow/answer/17102997" target="_blank" rel="noreferrer">Create &amp; use your avatar in Google Flow</a>：用 <code>@me</code> 把你自己的形象放进视频。</li><li><a href="https://support.google.com/flow/answer/17069754" target="_blank" rel="noreferrer">Use keyboard shortcuts in Google Flow</a>：快捷键表。</li><li><a href="https://support.google.com/flow/answer/17025472" target="_blank" rel="noreferrer">Manage your data in Google Flow</a>：数据怎么用、怎么删。</li><li><a href="https://support.google.com/flow/answer/17571126" target="_blank" rel="noreferrer">Download your Google Flow data</a>：通过 Google Takeout 导出全部项目。</li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro 权益清单</a>：Pro 里 Flow 与 Flow Music 的权益原文。</li></ul><p>官方博客，按时间排：</p><ul><li><a href="https://blog.google/innovation-and-ai/products/google-flow-veo-ai-filmmaking-tool/" target="_blank" rel="noreferrer">Meet Flow: AI-powered filmmaking with Veo 3</a>：2025 年 5 月的发布文。</li><li><a href="https://blog.google/innovation-and-ai/products/flow-video-tips/" target="_blank" rel="noreferrer">5 tips for getting started with Flow</a>：2025-06-25，官方的提示词要素，以及 Jump to 与 Extend 的定义。</li><li><a href="https://blog.google/innovation-and-ai/products/veo-updates-flow/" target="_blank" rel="noreferrer">Introducing Veo 3.1 and advanced capabilities in Flow</a>：2025-10-15，Ingredients、Frames、Extend 三个能力的官方解释。</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/flow-updates-february-2026/" target="_blank" rel="noreferrer">New ways to create and refine content in Flow</a>：2026-02-25，界面改版，图片生成并入 Flow。</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/flow-updates/" target="_blank" rel="noreferrer">New agents, mobile apps and Gemini Omni for Google Flow and Google Flow Music</a>：2026-05-19，Agent、Tools、手机应用的发布公告。</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/new-creative-controls-google-flow/" target="_blank" rel="noreferrer">Google Flow brings new creative control features to enhance video editing</a>：2026-08-27，首尾帧、1080p 与 4K 导出、360p 草稿。</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/" target="_blank" rel="noreferrer">Google Labs 博客</a>：后续更新从这里跟。</li></ul><p>其他入口：</p><ul><li><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">产品入口</a></li><li><a href="https://labs.google/flow/tv" target="_blank" rel="noreferrer">Flow TV</a>：官方的片段展示页，用屏幕底部的遥控器能看到每个片段背后的提示词。<a href="https://labs.google/fx/faq" target="_blank" rel="noreferrer">labs.google/fx 的 FAQ</a>：帮助中心指向的数据与政策说明。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./google-pro.html">订阅与额度</a> — Pro 里还有哪些编码相关权益</li><li><a href="./canvas.html">Canvas</a> — 能点的原型</li><li><a href="./gemini-cheatsheet.html#选哪个工具">速查表</a> — 按任务选工具</li><li><a href="./ai-studio.html">AI Studio</a> — 在代码里调 Veo 与 Nano Banana</li><li><a href="./gemini-glossary.html">术语表</a> — Flow 在 Gemini 家族里的位置</li></ul>`,146))])}const y=r(i,[["render",d]]);export{k as __pageData,y as default};
